private fun zzUnpacktrans(packed: String, offset: Int, result: IntArray): Int {

var i: Int = 0
var j: Int = offset
var l: Int = packed.length
while (i < l) {
var count: Int = packed.get(i ++).code
var value: Int = packed.get(i ++).code
value --
do result[j ++] = value while (-- count > 0)
}
return j
}

